Path("templates/use_cases/includes/approval_history.html").write_text(
    '''<div class="app-card mb-4" id="approval" data-testid="approval-history">\n  <div class="card-header">\n    <strong>Freigabe- und Prüfverlauf</strong>\n    <div class="small text-muted mt-1">Jede Entscheidung bleibt mit ihrer Bewertung, Erstentscheidung, Auflage und unabhängigen Zweitprüfung getrennt nachvollziehbar. Neueste Entscheidung zuerst.</div>\n  </div>\n  <div class="list-group list-group-flush">\n    {% for approval in use_case.approval_decisions.all %}\n    <article class="list-group-item bg-transparent py-4" data-approval-id="{{ approval.pk }}">\n      <div class="d-flex flex-wrap justify-content-between align-items-start gap-3 mb-3">\n        <div>\n          <div class="eyebrow mb-1">Entscheidungsartefakt #{{ approval.pk }}</div>\n          <h3 class="h5 mb-1">{{ approval.get_decision_status_display }}</h3>\n          <div class="small text-muted">Erstellt {{ approval.created_at|date:"d.m.Y H:i" }}</div>\n        </div>\n        <div class="d-flex flex-wrap gap-2">\n          {% if approval.is_pending_second_approval %}\n          <span class="badge state-review">Zweitprüfung offen</span>\n          {% elif approval.is_returned_from_second_approval %}\n          <span class="badge state-blocked">Begründet zurückgegeben</span>\n          {% elif approval.second_approved_by %}\n          <span class="badge state-ready">Unabhängig bestätigt</span>\n          {% elif approval.is_final %}\n          <span class="badge state-ready">Finale Entscheidung</span>\n          {% else %}\n          <span class="badge state-review">Nicht final</span>\n          {% endif %}\n        </div>\n      </div>\n\n      <div class="border rounded p-3 mb-3" data-testid="assessment-step-{{ approval.pk }}">\n        <div class="d-flex flex-wrap justify-content-between gap-2 mb-2">\n          <strong>1. Bewertung v{{ approval.assessment.version }}</strong>\n          <span class="small text-muted">{{ approval.assessment.assessment_date|date:"d.m.Y" }}</span>\n        </div>\n        <dl class="row small mb-2">\n          <dt class="col-sm-4 text-muted">Rolle</dt><dd class="col-sm-8">Bewertende Person</dd>\n          <dt class="col-sm-4 text-muted">Person</dt><dd class="col-sm-8">{{ approval.assessment.assessed_by|default:"Nicht dokumentiert" }}</dd>\n          <dt class="col-sm-4 text-muted">Empfehlung</dt><dd class="col-sm-8">{{ approval.assessment.get_recommendation_display }}</dd>\n          <dt class="col-sm-4 text-muted">Confidence</dt><dd class="col-sm-8">{{ approval.assessment.confidence_label }}</dd>\n        </dl>\n        <div class="small text-muted mb-2">{{ approval.assessment.rationale }}</div>\n        {% if approval.assessment.evidence_url %}<a class="small" href="{{ approval.assessment.evidence_url }}" target="_blank" rel="noopener noreferrer">Bewertungsnachweis öffnen</a>{% endif %}\n      </div>\n\n      <div class="border rounded p-3 mb-3" data-testid="first-decision-step-{{ approval.pk }}">\n        <div class="d-flex flex-wrap justify-content-between gap-2 mb-2">\n          <strong>2. Erstentscheidung</strong>\n          <span class="small text-muted">{{ approval.created_at|date:"d.m.Y H:i" }}</span>\n        </div>\n        <dl class="row small mb-2">\n          <dt class="col-sm-4 text-muted">Rolle</dt><dd class="col-sm-8">Erstentscheidende Person</dd>\n          <dt class="col-sm-4 text-muted">Person</dt><dd class="col-sm-8">{{ approval.decided_by|default:"Nicht dokumentiert" }}</dd>\n          <dt class="col-sm-4 text-muted">Entscheidung</dt><dd class="col-sm-8">{{ approval.get_decision_status_display }}</dd>\n          <dt class="col-sm-4 text-muted">Governance-Grundlage</dt><dd class="col-sm-8">{% if approval.governance_confirmed %}Bestätigt{% else %}Nicht bestätigt{% endif %}</dd>\n        </dl>\n        <div class="text-preline small">{{ approval.rationale }}</div>\n      </div>\n\n      {% if approval.conditions or approval.second_approval_requested_at or approval.second_approval_assignee %}\n      <div class="border rounded p-3 mb-3" data-testid="conditions-step-{{ approval.pk }}">\n        <div class="d-flex flex-wrap justify-content-between gap-2 mb-2">\n          <strong>3. Auflagen und Prüfauftrag</strong>\n          <span class="small text-muted">{{ approval.second_approval_requested_at|date:"d.m.Y H:i"|default:"Kein separater Prüfauftrag" }}</span>\n        </div>\n        <dl class="row small mb-2">\n          <dt class="col-sm-4 text-muted">Auflage</dt><dd class="col-sm-8 text-preline">{{ approval.conditions|default:"Keine Auflage dokumentiert" }}</dd>\n          <dt class="col-sm-4 text-muted">Verantwortlich</dt><dd class="col-sm-8">{{ approval.condition_owner|default:"Nicht dokumentiert" }}</dd>\n          <dt class="col-sm-4 text-muted">Fälligkeit</dt><dd class="col-sm-8">{{ approval.condition_due_date|date:"d.m.Y"|default:"Nicht festgelegt" }}</dd>\n          <dt class="col-sm-4 text-muted">Bevorzugte Zweitprüfung</dt><dd class="col-sm-8">{{ approval.second_approval_assignee|default:"Nicht zugewiesen" }}</dd>\n        </dl>\n      </div>\n      {% endif %}\n\n      {% if approval.is_pending_second_approval %}\n      <div class="border rounded p-3" data-testid="second-review-step-{{ approval.pk }}">\n        <div class="d-flex flex-wrap justify-content-between align-items-start gap-3">\n          <div>\n            <strong>4. Unabhängige Zweitprüfung ausstehend</strong>\n            <div class="small text-muted mt-1">Bevorzugt zugewiesen: {{ approval.second_approval_assignee|default:"Nicht dokumentiert" }}. Andere unabhängige berechtigte Personen dürfen übernehmen.</div>\n          </div>\n          <a class="btn btn-sm btn-outline-secondary" href="{% url 'use_cases:second_approval_review' approval.pk %}">Zweitprüfung öffnen</a>\n        </div>\n      </div>\n      {% elif approval.is_returned_from_second_approval %}\n      <div class="border rounded p-3" data-testid="second-review-step-{{ approval.pk }}">\n        <div class="d-flex flex-wrap justify-content-between gap-2 mb-2">\n          <strong>4. Begründet zurückgegeben</strong>\n          <span class="small text-muted">{{ approval.second_approval_returned_at|date:"d.m.Y H:i" }}</span>\n        </div>\n        <dl class="row small mb-2">\n          <dt class="col-sm-4 text-muted">Rolle</dt><dd class="col-sm-8">Unabhängig prüfende Person</dd>\n          <dt class="col-sm-4 text-muted">Person</dt><dd class="col-sm-8">{{ approval.second_approval_returned_by|default:"Nicht dokumentiert" }}</dd>\n        </dl>\n        <div class="text-preline small">{{ approval.second_approval_return_reason }}</div>\n        <div class="small text-muted mt-2">Die Erstentscheidung bleibt als historisches Artefakt erhalten, wurde jedoch nicht final bestätigt.</div>\n      </div>\n      {% elif approval.second_approved_by %}\n      <div class="border rounded p-3" data-testid="second-review-step-{{ approval.pk }}">\n        <div class="d-flex flex-wrap justify-content-between gap-2 mb-2">\n          <strong>4. Unabhängig bestätigt</strong>\n          <span class="small text-muted">{{ approval.finalized_at|date:"d.m.Y H:i" }}</span>\n        </div>\n        <dl class="row small mb-0">\n          <dt class="col-sm-4 text-muted">Rolle</dt><dd class="col-sm-8">Unabhängig bestätigende Person</dd>\n          <dt class="col-sm-4 text-muted">Tatsächlich bestätigt</dt><dd class="col-sm-8">{{ approval.second_approved_by }}</dd>\n          <dt class="col-sm-4 text-muted">Bevorzugt zugewiesen</dt><dd class="col-sm-8">{{ approval.second_approval_assignee|default:"Nicht dokumentiert" }}</dd>\n        </dl>\n      </div>\n      {% elif approval.is_final %}\n      <div class="border rounded p-3" data-testid="final-step-{{ approval.pk }}">\n        <div class="d-flex flex-wrap justify-content-between gap-2">\n          <strong>3. Entscheidung finalisiert</strong>\n          <span class="small text-muted">{{ approval.finalized_at|date:"d.m.Y H:i" }}</span>\n        </div>\n        <div class="small text-muted mt-1">Für diesen Entscheidungstyp war keine unabhängige Zweitbestätigung erforderlich.</div>\n      </div>\n      {% endif %}\n    </article>\n    {% empty %}\n    <div class="list-group-item bg-transparent text-muted">Noch keine Freigabeentscheidung dokumentiert.</div>\n    {% endfor %}\n  </div>\n</div>\n''',
    encoding="utf-8",
)

Path("tests/test_decision_history.py").write_text(
    '''from datetime import timedelta\n\nimport pytest\nfrom django.contrib.auth.models import Group\nfrom django.urls import reverse\nfrom django.utils import timezone\n\nfrom ki_radar.accounts.models import User\nfrom ki_radar.accounts.permissions import GROUP_COORDINATOR\nfrom ki_radar.use_cases.models import ApprovalDecision, DecisionAssessment, UseCase\n\n\ndef make_coordinator(username, business_unit):\n    user = User.objects.create_user(\n        username=username,\n        password="VerySecureTestPassword!123",\n        business_unit=business_unit,\n    )\n    group, _ = Group.objects.get_or_create(name=GROUP_COORDINATOR)\n    user.groups.add(group)\n    return user\n\n\ndef make_use_case(owner, coordinator, business_unit):\n    return UseCase.objects.create(\n        title="Auditierbarer Angebotsvergleich",\n        summary="Angebote nachvollziehbar vergleichen.",\n        problem_statement="Die bisherige Auswahl ist nicht ausreichend nachvollziehbar.",\n        business_unit=business_unit,\n        affected_process="Lieferantenauswahl",\n        business_owner=owner,\n        coordinator=coordinator,\n        technical_owner=coordinator,\n        expected_benefit="Entscheidungen schneller und prüfbar treffen.",\n        decision_status=UseCase.DecisionStatus.READY,\n    )\n\n\ndef make_assessment(use_case, assessor, *, version, rationale, recommendation):\n    return DecisionAssessment.objects.create(\n        use_case=use_case,\n        version=version,\n        assessed_by=assessor,\n        business_value=UseCase.Level.HIGH,\n        strategic_fit=UseCase.Level.HIGH,\n        technical_feasibility=UseCase.Level.HIGH,\n        data_readiness=UseCase.Level.MEDIUM,\n        risk_complexity=UseCase.Level.MEDIUM,\n        evidence_quality=DecisionAssessment.EvidenceQuality.REPRESENTATIVE,\n        evidence_recency=DecisionAssessment.ConfidenceFactor.SOLID,\n        evidence_coverage=DecisionAssessment.ConfidenceFactor.SOLID,\n        independent_review=DecisionAssessment.ConfidenceFactor.SOLID,\n        assumptions_resolved=DecisionAssessment.ConfidenceFactor.SOLID,\n        evidence_url=f"https://example.com/evidence-v{version}",\n        rationale=rationale,\n        governance_precheck_completed=True,\n        recommendation=recommendation,\n    )\n\n\n@pytest.fixture\ndef decision_history_case(owner, coordinator, business_unit):\n    assessor = make_coordinator("history-assessor", business_unit)\n    first_decider = make_coordinator("history-first-decider", business_unit)\n    preferred_reviewer = make_coordinator("history-preferred-reviewer", business_unit)\n    actual_reviewer = make_coordinator("history-actual-reviewer", business_unit)\n    use_case = make_use_case(owner, coordinator, business_unit)\n    return use_case, assessor, first_decider, preferred_reviewer, actual_reviewer\n\n\n@pytest.mark.django_db\ndef test_detail_shows_complete_confirmed_approval_chain(\n    client, owner, decision_history_case\n):\n    use_case, assessor, first_decider, preferred_reviewer, actual_reviewer = (\n        decision_history_case\n    )\n    assessment = make_assessment(\n        use_case,\n        assessor,\n        version=3,\n        rationale="Bewertung v3 mit belastbarer Evidenz.",\n        recommendation=UseCase.DecisionStatus.APPROVED_WITH_CONDITIONS,\n    )\n    now = timezone.now()\n    approval = ApprovalDecision.objects.create(\n        use_case=use_case,\n        assessment=assessment,\n        decision_status=UseCase.DecisionStatus.APPROVED_WITH_CONDITIONS,\n        rationale="Erstentscheidung mit klarer Betriebsauflage.",\n        decided_by=first_decider,\n        governance_confirmed=True,\n        conditions="Monitoring vor Pilotstart aktivieren.",\n        condition_owner=owner,\n        condition_due_date=timezone.localdate() + timedelta(days=14),\n        second_approval_assignee=preferred_reviewer,\n        second_approval_requested_at=now - timedelta(hours=2),\n        second_approved_by=actual_reviewer,\n        finalized_at=now,\n    )\n    client.force_login(owner)\n\n    response = client.get(reverse("use_cases:detail", args=[use_case.pk]))\n    body = response.content.decode()\n\n    assert response.status_code == 200\n    assert 'data-testid="approval-history"' in body\n    assert "1. Bewertung v3" in body\n    assert "Bewertung v3 mit belastbarer Evidenz" in body\n    assert "2. Erstentscheidung" in body\n    assert "Erstentscheidung mit klarer Betriebsauflage" in body\n    assert "3. Auflagen und Prüfauftrag" in body\n    assert "Monitoring vor Pilotstart aktivieren" in body\n    assert "4. Unabhängig bestätigt" in body\n    assert first_decider.get_display_name() in body\n    assert preferred_reviewer.get_display_name() in body\n    assert actual_reviewer.get_display_name() in body\n    assert body.index("1. Bewertung v3") < body.index("2. Erstentscheidung")\n    assert body.index("2. Erstentscheidung") < body.index("3. Auflagen und Prüfauftrag")\n    assert body.index("3. Auflagen und Prüfauftrag") < body.index("4. Unabhängig bestätigt")\n    assert f'data-approval-id="{approval.pk}"' in body\n\n\n@pytest.mark.django_db\ndef test_detail_shows_reasoned_return_without_overwriting_first_decision(\n    client, owner, decision_history_case\n):\n    use_case, assessor, first_decider, preferred_reviewer, actual_reviewer = (\n        decision_history_case\n    )\n    assessment = make_assessment(\n        use_case,\n        assessor,\n        version=1,\n        rationale="Bewertung für Rückgabefall.",\n        recommendation=UseCase.DecisionStatus.APPROVED_WITH_CONDITIONS,\n    )\n    approval = ApprovalDecision.objects.create(\n        use_case=use_case,\n        assessment=assessment,\n        decision_status=UseCase.DecisionStatus.APPROVED_WITH_CONDITIONS,\n        rationale="Historische Erstentscheidung bleibt erhalten.",\n        decided_by=first_decider,\n        governance_confirmed=True,\n        conditions="Abnahmekriterium konkretisieren.",\n        condition_owner=owner,\n        condition_due_date=timezone.localdate() + timedelta(days=7),\n        second_approval_assignee=preferred_reviewer,\n        second_approval_requested_at=timezone.now() - timedelta(hours=1),\n        second_approval_returned_by=actual_reviewer,\n        second_approval_returned_at=timezone.now(),\n        second_approval_return_reason="Das Abnahmekriterium ist noch nicht prüfbar.",\n    )\n    before = (approval.rationale, approval.decided_by_id, approval.decision_status)\n    client.force_login(owner)\n\n    response = client.get(use_case.get_absolute_url())\n    body = response.content.decode()\n    approval.refresh_from_db()\n\n    assert response.status_code == 200\n    assert "4. Begründet zurückgegeben" in body\n    assert "Das Abnahmekriterium ist noch nicht prüfbar" in body\n    assert "Die Erstentscheidung bleibt als historisches Artefakt erhalten" in body\n    assert "Historische Erstentscheidung bleibt erhalten" in body\n    assert (approval.rationale, approval.decided_by_id, approval.decision_status) == before\n\n\n@pytest.mark.django_db\ndef test_detail_keeps_multiple_decisions_linked_to_their_assessment_versions(\n    client, owner, decision_history_case\n):\n    use_case, assessor, first_decider, preferred_reviewer, actual_reviewer = (\n        decision_history_case\n    )\n    old_assessment = make_assessment(\n        use_case,\n        assessor,\n        version=1,\n        rationale="Alte Bewertungsversion eins.",\n        recommendation=UseCase.DecisionStatus.DEFERRED,\n    )\n    old_decision = ApprovalDecision.objects.create(\n        use_case=use_case,\n        assessment=old_assessment,\n        decision_status=UseCase.DecisionStatus.DEFERRED,\n        rationale="Historisch zunächst zurückgestellt.",\n        decided_by=first_decider,\n        governance_confirmed=True,\n        finalized_at=timezone.now() - timedelta(days=20),\n    )\n    ApprovalDecision.objects.filter(pk=old_decision.pk).update(\n        created_at=timezone.now() - timedelta(days=20)\n    )\n    new_assessment = make_assessment(\n        use_case,\n        assessor,\n        version=2,\n        rationale="Neue Bewertungsversion zwei.",\n        recommendation=UseCase.DecisionStatus.APPROVED_WITH_CONDITIONS,\n    )\n    new_decision = ApprovalDecision.objects.create(\n        use_case=use_case,\n        assessment=new_assessment,\n        decision_status=UseCase.DecisionStatus.APPROVED_WITH_CONDITIONS,\n        rationale="Später mit Auflage freigegeben.",\n        decided_by=first_decider,\n        governance_confirmed=True,\n        conditions="Monitoring aktivieren.",\n        condition_owner=owner,\n        condition_due_date=timezone.localdate() + timedelta(days=7),\n        second_approval_assignee=preferred_reviewer,\n        second_approval_requested_at=timezone.now() - timedelta(hours=2),\n        second_approved_by=actual_reviewer,\n        finalized_at=timezone.now(),\n    )\n    client.force_login(owner)\n\n    response = client.get(use_case.get_absolute_url())\n    body = response.content.decode()\n\n    assert response.status_code == 200\n    assert "Historisch zunächst zurückgestellt" in body\n    assert "Alte Bewertungsversion eins" in body\n    assert "Später mit Auflage freigegeben" in body\n    assert "Neue Bewertungsversion zwei" in body\n    assert body.index(f'data-approval-id="{new_decision.pk}"') < body.index(\n        f'data-approval-id="{old_decision.pk}"'\n    )\n    assert body.index("Neue Bewertungsversion zwei") < body.index(\n        "Alte Bewertungsversion eins"\n    )\n''',
    encoding="utf-8",
)
